import os
import logging
logger = logging.getLogger(__name__)


class AirphoneBipCollectorConfigurator:
    def add_bip(self, ne_log_name, ne_log_configuration):
        comu_type = self.airphone_information_provider.get_airphone_common_unit_type()

        if comu_type == 'ASIL':
            self.create_asil_bip_collectors(ne_log_name=ne_log_name)
        elif comu_type == 'ASIK':
            self.create_ap_asik_bip_collector(ne_log_name=ne_log_name)

    def get_bip_trace_capture_interface(self):
        """
        Determine the capture interface on the airphone
        """
        comu_type = self.airphone_information_provider.get_airphone_common_unit_type()

        if comu_type == 'ASIL':
            interface = self.airphone_information_provider.get_airphone_mirroring_interface(self.ne_id)
            return interface if interface else 'etha01.309'
        elif comu_type == 'ASIK':
            return 'etha01'

    def get_airphone_executor(self, node_id):
        """
        Get the lmp connection details from the testline configuration

        :param int node_id: The index of the ue in the testline configuration
        """
        lmp_connection = self.tl_config_information_provider.get_ue_lmp_connection(node_id=self.ne_id)

        return {'host': lmp_connection.addr,
                'user': lmp_connection.username,
                'password': lmp_connection.password}

    def create_ap_asik_bip_collector(self, ne_log_name):
        """
        Creates the collector configuration for BIP trace collection on ASIK airphone devices

        :param str ne_log_name: The log name of the bip trace
        """
        # switch the mirroring mode to manual, so we can use the tcpdump collector
        os.system('''sed -i "s|MIRRORING_MODE='.*'|MIRRORING_MODE='manual'|" /opt/wts/latest/apMirroringConfig.sh''')

        # download the gulp tool from rotta, since this is required on ASIK airphone devices
        os.system('wget -P /tmp/ https://artifactory-espoo1.ext.net.nokia.com/artifactory/mnpute-rotta-local/nuecker/gulp')

        interface = self.get_bip_trace_capture_interface()

        airphone_executor = self.get_airphone_executor(self.ne_id)

        script_paths = ['/opt/wts/latest/apMirroring.sh',
                        '/opt/wts/latest/apMirroringConfig.sh',
                        '/tmp/gulp']

        tcpdump_collector = {'name': f'{ne_log_name}_tcpdump',
                             'type': 'tcpdump',
                             'options': f'-i {interface}',
                             'executor': airphone_executor}
        self._collector_configuration_data.append(tcpdump_collector)

        ap_bip_collector = {'name': f'{ne_log_name}',
                            'type': 'airphone_l1l2bip',
                            'collector': f'{ne_log_name}_tcpdump',
                            'executor': airphone_executor,
                            'script_paths': script_paths}
        self._collector_configuration_data.append(ap_bip_collector)
        self._collector_configuration_data.add_mapping_entry(
            log_type='bip',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=ap_bip_collector)

    def create_asil_bip_collectors(self, ne_log_name):
        """
        Creates the collector configuration for BIP trace collection on ASIL airphone devices

        :param str ne_log_name: The log name of the bip trace
        """
        script_path = ['/opt/wts/latest/sosReport_ASIL/airphone_mirror.sh',
                       '/opt/wts/latest/sosReport_ASIL/gnbMirroring.py']
        interface = self.get_bip_trace_capture_interface()

        remote_context_commands = {'setup': './airphone_mirror.sh',
                                   'teardown': './airphone_mirror.sh --stop'}

        airphone_executor = self.get_airphone_executor(self.ne_id)

        tcpdump_collector = {'name': f'{ne_log_name}_tcpdump',
                             'type': 'tcpdump',
                             'options': f'-i {interface}',
                             'executor': airphone_executor}
        self._collector_configuration_data.append(tcpdump_collector)

        collector = {'type': 'airphone_l1l2bip',
                     'name': f'{ne_log_name}',
                     'collector': f'{ne_log_name}_tcpdump',
                     'executor': airphone_executor,
                     'script_paths': script_path,
                     'command_line': remote_context_commands}
        self._collector_configuration_data.append(collector)

        self._collector_configuration_data.add_mapping_entry(
            log_type='bip',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=collector)
